page Home "/" {
  meta title="Nimbus" description="Nimbus: rápido, simple y abierto."

  state users = 0
  ref stats
  ref observer
  ref frame
  ref startedAt

  computed label = users.toLocaleString("es-AR") + "+"

  fn reducedMotion() {
    return window.matchMedia("(prefers-reduced-motion: reduce)").matches
  }

  fn tick(now) {
    let t = Math.min((now - startedAt) / 1800, 1)
    users = Math.round(12000 * (1 - Math.pow(1 - t, 3)))
    if t < 1 {
      frame = requestAnimationFrame(tick)
    }
  }

  fn startCount() {
    observer?.disconnect()
    if reducedMotion() {
      users = 12000
      return
    }
    startedAt = performance.now()
    frame = requestAnimationFrame(tick)
  }

  fn goToFeatures() {
    document.getElementById("features")?.scrollIntoView({ behavior: reducedMotion() ? "auto" : "smooth" })
  }

  mount {
    if reducedMotion() || !("IntersectionObserver" in window) {
      users = 12000
    } else {
      observer = new IntersectionObserver(entries => entries[0].isIntersecting && startCount(), { threshold: 0.5 })
      observer.observe(stats)
    }
    cleanup {
      observer?.disconnect()
      if frame {
        cancelAnimationFrame(frame)
      }
    }
  }

  column class="page" gap=0 {
    column class="hero" tag=header align=center justify=center gap=5 pad=6 {
      title "Nimbus" tag=h1 class="hero-title" animate=rise duration=700
      text "La plataforma ligera para lanzar tus ideas en minutos, no en semanas." large class="hero-sub" tag=p animate=fade delay=200
      button "Empezar" primary class="hero-cta" hover=grow animate=pop delay=400 -> goToFeatures()
    }

    column tag=main class="content" gap=16 pad=6 align=center {
      grid id="features" class="features" cols=1 md:cols=3 gap=6 {
        card class="feature" reveal pad=6 gap=3 {
          icon "zap" size=28 primary
          title "Rápido" tag=h3
          text "Carga al instante y responde sin esperas." muted tag=p
        }
        card class="feature" reveal pad=6 gap=3 {
          icon "sparkles" size=28 primary
          title "Simple" tag=h3
          text "Todo lo que necesitás, nada que te estorbe." muted tag=p
        }
        card class="feature" reveal pad=6 gap=3 {
          icon "unlock" size=28 primary
          title "Abierto" tag=h3
          text "Código abierto y sin ataduras, para siempre." muted tag=p
        }
      }

      column class="stats" ref=stats align=center gap=1 tag=section aria-label="12.000+ usuarios" {
        text label class="stat-number" tag=p aria-hidden="true"
        text "usuarios confían en Nimbus" muted large tag=p aria-hidden="true"
      }
    }
  }

  style {
    .page {
      min-height: 100vh;
    }
    .hero {
      position: relative;
      min-height: 80vh;
      text-align: center;
      color: #fff;
      overflow: hidden;
      background: linear-gradient(120deg, #6366f1, #8b5cf6, #ec4899, #06b6d4, #6366f1);
      background-size: 400% 400%;
      animation: nimbus-gradient 20s ease-in-out infinite;
    }
    .hero-title {
      font-size: clamp(3rem, 10vw, 6.5rem);
      font-weight: 800;
      letter-spacing: -0.03em;
      margin: 0;
      color: #fff;
      text-shadow: 0 8px 30px rgba(0, 0, 0, 0.2);
    }
    .hero-sub {
      max-width: 36rem;
      font-size: 1.25rem;
      opacity: 0.92;
      margin: 0;
      color: #fff;
    }
    .hero-cta {
      font-size: 1.1rem;
      padding: 0.85rem 2.2rem;
      border-radius: 999px;
      background: #fff;
      color: #4f46e5;
      border: none;
      box-shadow: 0 10px 30px rgba(0, 0, 0, 0.18);
      transition: transform 0.35s ease, box-shadow 0.35s ease;
    }
    .hero-cta:hover {
      transform: scale(1.08);
      box-shadow: 0 14px 40px rgba(0, 0, 0, 0.25);
    }
    .content {
      padding-top: 5rem;
      padding-bottom: 6rem;
    }
    .features {
      width: 100%;
      max-width: 64rem;
    }
    .feature {
      border-radius: 1rem;
      text-align: left;
    }
    .stat-number {
      font-size: clamp(3rem, 8vw, 5rem);
      font-weight: 800;
      margin: 0;
      font-variant-numeric: tabular-nums;
      background: linear-gradient(120deg, #6366f1, #ec4899);
      -webkit-background-clip: text;
      background-clip: text;
      color: transparent;
    }
    @keyframes nimbus-gradient {
      0% { background-position: 0% 50%; }
      50% { background-position: 100% 50%; }
      100% { background-position: 0% 50%; }
    }
    @media (prefers-reduced-motion: reduce) {
      .hero {
        animation: none;
        background-position: 50% 50%;
      }
      .hero-cta,
      .hero-cta:hover {
        transition: none;
        transform: none;
      }
    }
  }
}

