page Home "/" {
  meta title="Nimbus" description="Nimbus: rápido, simple y abierto."

  state count = 0
  computed shown = String(count).replace(/\B(?=(\d{3})+(?!\d))/g, ".") + "+"

  ref stat
  ref obs
  ref raf
  ref timer
  ref t0
  ref reduce
  ref started = false
  ref done = false

  fn finish() {
    done = true
    if raf { cancelAnimationFrame(raf) }
    if timer { clearTimeout(timer) }
    count = 12000
  }

  fn startCount() {
    if started { return }
    started = true
    if obs { obs.disconnect() }
    if reduce {
      finish()
      return
    }
    t0 = performance.now()
    raf = requestAnimationFrame(step)
    timer = setTimeout(finish, 1300)
  }

  fn step(now) {
    if done { return }
    let p = Math.min(Math.max((now - t0) / 1200, 0), 1)
    if p >= 1 {
      finish()
      return
    }
    let eased = 1 - Math.pow(1 - p, 3)
    count = Math.min(Math.round(12000 * eased), 12000)
    raf = requestAnimationFrame(step)
  }

  mount {
    reduce = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches
    if typeof IntersectionObserver == "undefined" {
      startCount()
    } else {
      obs = new IntersectionObserver(entries => entries.some(e => e.isIntersecting) && startCount(), { threshold: 0.3 })
      obs.observe(stat)
    }
    cleanup {
      if obs { obs.disconnect() }
      if raf { cancelAnimationFrame(raf) }
      if timer { clearTimeout(timer) }
