import { createSignal, onCleanup, onMount } from "solid-js";
import { observeOnce, usePrefersReducedMotion } from "./motion";

const TARGET = 12000;
const DURATION = 2000;

export default function Counter() {
  let el!: HTMLDivElement;
  const reduced = usePrefersReducedMotion();
  const [value, setValue] = createSignal(0);
  let frame = 0;

  const format = (n: number) => n.toLocaleString("es-AR");

  onMount(() => {
    const start = () => {
      if (reduced()) {
        setValue(TARGET);
        return;
      }
      const t0 = performance.now();
      const tick = (now: number) => {
        const p = Math.min((now - t0) / DURATION, 1);
        const eased = 1 - Math.pow(1 - p, 3);
        setValue(Math.round(eased * TARGET));
        if (p < 1) frame = requestAnimationFrame(tick);
      };
      frame = requestAnimationFrame(tick);
    };
    const stop = observeOnce(el, start, { threshold: 0.5 });
    onCleanup(() => {
      stop();
      cancelAnimationFrame(frame);
    });
  });

  return (
    <section class="px-6 pb-24 pt-8 text-center">
      <div ref={el}>
        <p class="sr-only">Más de {format(TARGET)} usuarios</p>
