import { createSignal, onCleanup, onMount } from "solid-js";
import { observeOnce, usePrefersReducedMotion } from "./motion";

const TARGET = 12000;
const DURATION = 1500;

export default function Counter() {
  let el!: HTMLDivElement;
  const reduced = usePrefersReducedMotion();
  const [value, setValue] = createSignal(0);
  let frame = 0;
  let finishTimer: ReturnType<typeof setTimeout> | undefined;
  let done = false;

  const format = (n: number) => n.toLocaleString("es-AR");

  const finish = () => {
    done = true;
    cancelAnimationFrame(frame);
    if (finishTimer !== undefined) clearTimeout(finishTimer);
    setValue(TARGET);
  };

  onMount(() => {
    const start = () => {
      if (reduced()) {
        finish();
        return;
      }
      const t0 = performance.now();
      const tick = (now: number) => {
        if (done) return;
        const p = Math.min(Math.max((now - t0) / DURATION, 0), 1);
        if (p >= 1) {
          finish();
          return;
        }
        const eased = 1 - Math.pow(1 - p, 3);
        setValue(Math.min(TARGET, Math.round(eased * TARGET)));
        frame = requestAnimationFrame(tick);
      };
      frame = requestAnimationFrame(tick);
      // Garantiza que el valor final siempre sea exacto, aunque rAF se retrase o pause.
      finishTimer = setTimeout(finish, DURATION + 50);
    };
    const stop = observeOnce(el, start, { threshold: 0.5 });
    onCleanup(() => {
      stop();
      done = true;
      cancelAnimationFrame(frame);
      if (finishTimer !== undefined) clearTimeout(finishTimer);
    });
  });

  return (
    <section class="px-6 pb-24 pt-8 text-center">
      <div ref={el}>
        <span class="bg-gradient-to-r from-indigo-400 via-violet-400 to-teal-300 bg-clip-text text-6xl font-extrabold tabular-nums text-transparent sm:text-7xl">
          {format(value())}+
