import { createSignal, For, onCleanup, onMount } from "solid-js";
import { observeOnce, usePrefersReducedMotion } from "./reducedMotion";

const features = [
  { title: "Rápido", text: "Carga en milisegundos, incluso con conexiones lentas.", icon: "⚡" },
  { title: "Simple", text: "Sin configuraciones eternas: empezás en un minuto.", icon: "✨" },
  { title: "Abierto", text: "Código abierto y hecho junto a la comunidad.", icon: "🌍" },
];

export default function Features() {
  let container: HTMLDivElement | undefined;
  const [visible, setVisible] = createSignal(false);
  const reduced = usePrefersReducedMotion();

  onMount(() => {
    if (!container) return;
    const stop = observeOnce(container, () => setVisible(true), 0.2);
    onCleanup(stop);
  });

  const shown = () => visible() || reduced();

  return (
    <section class="mx-auto max-w-5xl px-6 py-24">
      <h2 class="mb-12 text-center text-3xl font-bold text-slate-900 sm:text-4xl">
        Por qué Nimbus
      </h2>
      <div ref={container} class="grid gap-6 sm:grid-cols-3">
        <For each={features}>
          {(feature, i) => (
            <article
              class="rounded-2xl border border-slate-200 bg-white p-8 shadow-sm transition-all duration-700 ease-out motion-reduce:transition-none"
              classList={{
                "opacity-100 translate-y-0": shown(),
                "opacity-0 translate-y-8": !shown(),
              }}
              style={{ "transition-delay": reduced() ? "0ms" : `${i() * 200}ms` }}
            >
              <div class="mb-4 text-3xl" aria-hidden="true">
                {feature.icon}
              </div>
              <h3 class="mb-2 text-xl font-semibold text-slate-900">{feature.title}</h3>
              <p class="text-slate-600">{feature.text}</p>
            </article>
          )}
        </For>
      </div>
    </section>
  );
}

