import { createEffect, createSignal, onCleanup, onMount } from "solid-js";
import { observeOnce, usePrefersReducedMotion } from "./reducedMotion";

const TARGET = 12000;
const DURATION = 2000;

export default function Counter() {
  let el: HTMLDivElement | undefined;
  const [value, setValue] = createSignal(0);
  const [started, setStarted] = createSignal(false);
  const reduced = usePrefersReducedMotion();
  let frame = 0;

  onMount(() => {
    if (!el) return;
    const stop = observeOnce(el, () => setStarted(true), 0.5);
    onCleanup(stop);
  });

  createEffect(() => {
    if (!started()) return;
    if (reduced()) {
      cancelAnimationFrame(frame);
      setValue(TARGET);
      return;
    }
    if (value() >= TARGET) return;
    const start = performance.now();
    const tick = (now: number) => {
      const t = Math.min((now - start) / DURATION, 1);
      const eased = 1 - Math.pow(1 - t, 3);
      setValue(Math.round(eased * TARGET));
      if (t < 1) frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
  });

  onCleanup(() => cancelAnimationFrame(frame));

  const formatted = () => value().toLocaleString("es-AR");

  return (
    <section class="bg-slate-900 px-6 py-24 text-center text-white">
      <div ref={el}>
        <p class="sr-only">Más de 12.000 usuarios confían en Nimbus</p>
        <p
          aria-hidden="true"
          class="bg-gradient-to-r from-sky-400 via-indigo-400 to-fuchsia-400 bg-clip-text text-6xl font-extrabold tabular-nums text-transparent sm:text-7xl"
        >
          {formatted()}+
        </p>
        <p aria-hidden="true" class="mt-4 text-lg text-slate-300">
          usuarios ya confían en Nimbus
        </p>
      </div>
    </section>
  );
}

