      <section class="relative flex min-h-screen items-center justify-center overflow-hidden px-6">
        <div class="nimbus-gradient absolute inset-0" aria-hidden="true" />
        <div class="absolute inset-0 bg-black/20" aria-hidden="true" />

        <div class="relative z-10 max-w-2xl text-center text-white">
          <h1 class="text-6xl font-extrabold tracking-tight drop-shadow-lg sm:text-8xl">
            Nimbus
          </h1>
          <p class="mt-6 text-lg text-white/90 sm:text-2xl">
            La plataforma liviana para construir, lanzar y crecer sin fricción.
          </p>
          <button
            type="button"
            class="mt-10 rounded-full bg-white px-10 py-4 text-lg font-semibold text-indigo-600 shadow-xl transition-transform duration-300 ease-out hover:scale-110 focus:outline-none focus-visible:ring-4 focus-visible:ring-white/60 motion-reduce:transition-none motion-reduce:hover:scale-100"
